def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Start of a new field
        if i == len(line):
            # End of line - add the last field if we've been processing
            if i > 0 or not fields:  # Empty line or we just finished a field
                if i == len(line) and fields:
                    # We've just finished processing, don't add another field
                    pass
                elif i == 0:
                    # Empty line
                    fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i == len(line) or line[i] == ',':
                            if i < len(line):
                                i += 1  # Skip the comma
                            fields.append(field)
                            break
                        else:
                            # Malformed: closing quote not followed by comma or end
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Malformed: quote in unquoted field
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < len(line):
                i += 1  # Skip the comma

    return fields

